examples.query:
query Authorizations($query: SqlQuery, $limit: Int) {
  authorizations(query: $query, limit: $limit) {
    items {
      authorization_id
      merchant_uid
      amount
      currency
      status
      fee_mode
      fees
      authorization_date
      expiration_date
      transaction_id
    }
    total_row_count
  }
}

mutation CreateWalletAuthorization(
  $merchant_uid: String!
  $digital_wallet_payload: String!
  $wallet_type: WalletType
  $amount: Int
) {
  createWalletAuthorization(
    merchant_uid: $merchant_uid
    digital_wallet_payload: $digital_wallet_payload
    wallet_type: $wallet_type
    amount: $amount
  ) {
    authorization_id
    amount
    status
  }
}

mutation CreateCapture(
  $merchant_uid: String!
  $authorization_id: String!
  $amount: Int!
) {
  createCapture(
    merchant_uid: $merchant_uid
    authorization_id: $authorization_id
    amount: $amount
  ) {
    transaction_id
    merchant_uid
    gross_amount
    net_amount
    status
    fee_mode
    authorization_id
  }
}

